<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Controllers\Api\V1\Concerns\ApiResponse; use App\Http\Resources\Api\V1\CollectibleResource; use App\Models\Collectible; use Illuminate\Http\Request; class CollectionController extends Controller{use ApiResponse; private function list(Request $r,?string $type=null){$owned=$r->user()->userCollectibles()->pluck('collectible_id')->all(); $q=Collectible::where('is_active',true); if($type){$q->where('type',$type);} $data=$q->orderBy('type')->orderBy('name')->get()->map(function($c)use($owned){$c->unlocked=in_array($c->id,$owned,true); return $c;}); return $this->success('Collection utilisateur.', CollectibleResource::collection($data));} public function index(Request $r){return $this->list($r);} public function personalities(Request $r){return $this->list($r,'personality');} public function monuments(Request $r){return $this->list($r,'monument');}}
